text:
Here's your water tracker: tap **+ Glass** after each one, and it counts up to your goal of 8. It saves your count for today and starts fresh tomorrow.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; background: #eef6fb; color: #123; text-align: center; }
  h1 { font-size: 1.4rem; margin: 0 0 4px; }
  #sub { color: #456; margin-bottom: 20px; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 360px; margin: 0 auto 20px; }
  .g { width: 64px; height: 84px; border: 3px solid #3a8fc4; border-radius: 6px 6px 16px 16px; background: #fff; position: relative; overflow: hidden; cursor: pointer; }
  .g.full::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 80%; background: #5bb8ee; }
  #bar { height: 12px; max-width: 360px; margin: 0 auto 8px; background: #d3e6f2; border-radius: 6px; overflow: hidden; }
  #fill { height: 100%; width: 0; background: #2b86c5; transition: width .3s; }
  #msg { min-height: 1.4em; font-weight: 600; margin-bottom: 16px; }
  button { font-size: 1rem; padding: 10px 18px; margin: 4px; border: 0; border-radius: 8px; background: #2b86c5; color: #fff; cursor: pointer; }
  button.alt { background: #8aa7b8; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="sub"></div>
  <div id="glasses"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="count"></div>
  <div id="msg"></div>
  <button id="add">+ Glass</button>
  <button id="undo" class="alt">− Undo</button>
  <button id="reset" class="alt">Reset</button>
<script>
  var GOAL = 8;
  var key = "water-" + new Date().toISOString().slice(0, 10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}
  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }
  function draw() {
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < n ? " full" : "");
      d.setAttribute("data-i", i);
      d.onclick = function () {
        var i = parseInt(this.getAttribute("data-i"), 10);
        n = (n === i + 1) ? i : i + 1;
        save(); draw();
      };
      box.appendChild(d);
    }
    document.getElementById("sub").textContent = new Date().toDateString();
    document.getElementById("count").textContent = n + " of " + GOAL + " glasses";
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Nicely done!" : (GOAL - n) + " to go";
  }
  document.getElementById("add").onclick = function () { n++; save(); draw(); };
  document.getElementById("undo").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
